test_prefix:
public void testPropertyCompareToHour_5_oe() {
    LocalTime test1 = new LocalTime(TEST_TIME1);
    LocalTime test2 = new LocalTime(TEST_TIME2);
    try {
        test1.hourOfDay().compareTo((ReadablePartial) null);
    } catch (IllegalArgumentException ex) {}

    DateTime dt1 = new DateTime(TEST_TIME1);
    DateTime dt2 = new DateTime(TEST_TIME2);
    assertEquals(true,test1.hourOfDay().compareTo(dt2)< 0);
}

mut_method_definition:
@Override
    public int compareTo(ReadablePartial partial) {
        // override to perform faster
        if (this == partial) {
            return 0;
        }
        if (partial instanceof LocalTime) {
            LocalTime other = (LocalTime) partial;
            if (iChronology.equals(other.iChronology)) {
                return (iLocalMillis < other.iLocalMillis ? -1 :
                            (iLocalMillis == other.iLocalMillis ? 0 : 1));

            }
        }
        return super.compareTo(partial);
    }

